#!/usr/bin/env bash
# Fails loudly when this working tree is a raw git clone, a downloaded zip, or a
# GitHub "Use this template" copy of TheForge itself, rather than a project
# generated by `copier copy` (ADR-0004).
#
# `copier.yml` sets `_subdirectory: template`, so a real render only ever
# contains what's under template/: it never has copier.yml or template/ at its
# root. Finding both at the root here means this tree is still the forge, not a
# generated project. The one working tree where that's correct is TheForge's own
# clone, which this script tells apart by remote: any remote whose URL names
# forger88/TheForge or forger88/TheForgeStaging is a legitimate forge-development clone (including a
# contributor's fork with an `upstream` remote). Anything else — a clone pushed
# to a new repo, a "Use this template" copy (fresh history, a different remote),
# or a zip extracted and re-initialised as its own repo — gets the loud failure.
#
# Usage: check-not-raw-clone.sh   (pre-commit runs it with no file arguments;
# see .pre-commit-config.yaml's always_run/pass_filenames).
set -euo pipefail

repo_root="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"

# Not a forge copy at all (e.g. a generated project, or some unrelated repo):
# nothing to check.
if [ ! -f "$repo_root/copier.yml" ] || [ ! -d "$repo_root/template" ]; then
  exit 0
fi

# A root .copier-answers.yml is not evidence of a real render (ADR-0009): this
# repository's own self-retrofit commits one at root, and a raw copy of root
# is byte-identical, answers file included. Only the remote (below) tells a
# genuine forge-development clone apart from a raw copy or template-button copy.

# TheForge's own working copy, including a contributor's fork: some remote
# names forger88/TheForge, or the private staging repository
# forger88/TheForgeStaging.
if git -C "$repo_root" remote -v 2>/dev/null | grep -qiE '(^|[/:])forger88/TheForge(Staging)?(\.git)?([[:space:]]|$)'; then
  exit 0
fi

cat >&2 <<'EOF'
============================================================================
 This looks like a raw copy of TheForge (a plain git clone, a downloaded
 zip, or GitHub's "Use this template" button) rather than a project
 generated by Copier.

 TheForge is a Copier TEMPLATE, not a project you work in directly: every
 Jinja placeholder is still unfilled, and the forge's own files are sitting
 where a generated project never has them.

 Delete this repository and generate a real one instead:

     copier copy --trust gh:forger88/TheForge <your-new-project-dir>

 See https://github.com/forger88/TheForge#using-it.

 (Legitimately working on TheForge itself? Add a remote that names
 forger88/TheForge or forger88/TheForgeStaging (the private staging
 repository), e.g. `git remote add upstream
 https://github.com/forger88/TheForge.git` or
 `https://github.com/forger88/TheForgeStaging.git`, whichever is yours,
 and this check will pass.)
============================================================================
EOF
exit 1
